// `video validate` on the media-range-* projects (task 038; PRD §6.2, §9.2;
// ADR-0008). A source end past the file is E_MEDIA_RANGE with the file and its
// line; a source shorter than its scene is E_MEDIA_SHORT_SOURCE unless loop or
// freeze is set. The clip is generated by tests/fixtures/media/generate.sh,
// which runs first. Each project is copied to a scratch dir, so nothing is
// written into tests/fixtures.
import { execFileSync, spawnSync } from "node:child_process";
import {
  cpSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { delimiter, join } from "node:path";
import { fileURLToPath } from "node:url";
import { after, before, describe, it } from "node:test";
import { strict as assert } from "node:assert";

const ROOT = fileURLToPath(new URL("../..", import.meta.url));
const BIN_DIR = join(ROOT, "node_modules", ".bin");
const PROJECTS = join(ROOT, "tests", "fixtures", "projects");
const SCRATCH = mkdtempSync(join(tmpdir(), "video-range-"));

/** Runs the installed `video` bin (node_modules/.bin, as `npx video` does). */
function video(args: string[], cwd: string) {
  const result = spawnSync(join(BIN_DIR, "video"), args, {
    cwd,
    encoding: "utf8",
    env: {
      ...process.env,
      PATH: `${BIN_DIR}${delimiter}${process.env["PATH"] ?? ""}`,
    },
  });
  if (result.error !== undefined) throw result.error;
  return {
    status: result.status,
    stdout: result.stdout,
    stderr: result.stderr,
  };
}

/** A scratch copy of a media-range project (its clip is generated first). */
function copyOf(name: string, as = name): string {
  const root = join(SCRATCH, as);
  cpSync(join(PROJECTS, name), root, { recursive: true });
  return root;
}

before(() => {
  execFileSync(
    "bash",
    [join(ROOT, "tests", "fixtures", "media", "generate.sh")],
    {
      stdio: "ignore",
    },
  );
});

after(() => rmSync(SCRATCH, { recursive: true, force: true }));

describe("video validate: source ranges against the file (task 038)", () => {
  it("overrun: exits 1 and names sourceEnd, the file and the line", () => {
    const run = video(["validate", copyOf("media-range-overrun")], ROOT);
    assert.equal(run.status, 1, run.stderr);
    assert.match(
      run.stderr,
      /ERROR index\.qmd:\d+[\s\S]*sourceEnd exceeds the source duration of "assets\/clip\.mp4"\./,
    );
    assert.equal(run.stdout, "");
  });

  it("overrun: --json names E_MEDIA_RANGE, the asset and the scene", () => {
    const run = video(
      ["validate", "--json", copyOf("media-range-overrun", "j")],
      ROOT,
    );
    assert.equal(run.status, 1, run.stderr);
    const [diagnostic] = JSON.parse(run.stdout) as Record<string, unknown>[];
    assert.equal(diagnostic?.["code"], "E_MEDIA_RANGE");
    assert.equal(diagnostic?.["assetPath"], "assets/clip.mp4");
    assert.equal(diagnostic?.["sceneId"], "scene-001");
    assert.equal(typeof diagnostic?.["line"], "number");
  });

  it("short: a 2 s source in a 4 s scene with no flag is E_MEDIA_SHORT_SOURCE", () => {
    const run = video(["validate", copyOf("media-range-short")], ROOT);
    assert.equal(run.status, 1, run.stderr);
    assert.match(
      run.stderr,
      /E_MEDIA_SHORT_SOURCE|source range of "assets\/clip\.mp4"/,
    );
    assert.match(run.stderr, /loop="true"/);
  });

  it('loop: the same range with loop="true" validates', () => {
    const run = video(["validate", copyOf("media-range-loop")], ROOT);
    assert.equal(run.status, 0, run.stderr);
    assert.match(run.stdout + run.stderr, /OK/);
  });

  it('freeze: the same range with freeze="true" validates', () => {
    const run = video(["validate", copyOf("media-range-freeze")], ROOT);
    assert.equal(run.status, 0, run.stderr);
  });

  it("short with loop added to a copy validates (the Human check)", () => {
    const root = copyOf("media-range-short", "short-loop");
    const file = join(root, "index.qmd");
    writeFileSync(
      file,
      readFileSync(file, "utf8").replace(
        'sourceEnd="2s"',
        'sourceEnd="2s"\n    loop="true"',
      ),
    );
    const run = video(["validate", root], ROOT);
    assert.equal(run.status, 0, run.stderr);
  });
});
